package com.shubhasai.monkeymart

import androidx.compose.ui.test.hasTestTag
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.performClick
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import java.lang.ref.WeakReference

@RunWith(AndroidJUnit4::class)
class MainActivityRecreateTest {

    @get:Rule
    val composeRule = createAndroidComposeRule<MainActivity>()

    @Test
    fun recreatedActivitiesAreNotRetained() {
        composeRule.waitUntil(timeoutMillis = 5_000) {
            composeRule.onAllNodes(hasTestTag("product_1")).fetchSemanticsNodes().isNotEmpty()
        }
        composeRule.onNodeWithTag("product_1").performClick()
        composeRule.waitUntil(timeoutMillis = 5_000) {
            composeRule.onAllNodes(hasTestTag("detail_loading")).fetchSemanticsNodes().isNotEmpty()
        }

        var firstRef: WeakReference<MainActivity>? = null
        composeRule.activityRule.scenario.onActivity { firstRef = WeakReference(it) }
        assertNotNull(firstRef?.get())

        repeat(3) { composeRule.activityRule.scenario.recreate() }

        for (attempt in 0 until 10) {
            Runtime.getRuntime().gc()
            System.runFinalization()
            if (firstRef?.get() == null) break
            Thread.sleep(100)
        }

        assertNull("Destroyed MainActivity is still reachable", firstRef?.get())
    }
}
